sys_script_client.script:
// Created Client Script as part of MSSCUSTODY-5334 to prepopulate amend fileds by taking valus from Trade.
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {


        //handling the prepopulation during onload when outcome is prepopulated
        var charRegex = /[^a-zA-Z0-9\s]/g;
        var taskType = g_scratchpad.tradeTaskType;
        var slashRegex = /\s/g;   //MSSCUSTODY-7158


        function regexCheck(inputValue) {
            var finalResult = inputValue.replace(charRegex, '');
            finalResult = finalResult.trim();
            finalResult = finalResult.replace(/\s/g, '');
            return finalResult;

        }

        if ((g_form.getValue('state') == 1 || g_form.getValue('state') == 2) && taskType == 'Maker') {
            var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtilsPassive');
            eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
            eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
            eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
            eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task_passive');
            eligbleCheck.getXMLAnswer(handleEligiblity);
        }



        function handleEligiblity(check) {
            //g_form.addInfoMessage('Eligibility' + check);
            if (check.toString() == 'true') {
                //pre populating the  values only if the outcome and market configured in the system property
                var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtilsPassive');
                ga.addParam('sysparm_name', 'getTradeFieldvalues');
                ga.addParam('sysparm_taskID', g_form.getUniqueValue());
                ga.addParam('sysparm_tradeID', g_form.getValue('trade_id'));
                ga.getXMLAnswer(populateField);
                //pre populating the  values only if the outcome and market configured in the system property
            }
        }

        function populateField(response) {
            if (response.toString() != 'false') { // populating only for active tasks
                var answer = JSON.parse(response);
                //handling special Characters
                var cusRef = answer.cusRef;
                if ((cusRef != null) && (cusRef != '') && (cusRef != undefined)) {
                    cusRef = regexCheck(cusRef);
                }
                var susAccNum = answer.susAccNum; //commented for format matching in RPA
                if ((susAccNum != null) && (susAccNum != '') && (susAccNum != undefined)) {
                    susAccNum = regexCheck(susAccNum)
                }
                var accOfClient = answer.accOfClient;
                if ((accOfClient != null) && (accOfClient != '') && (accOfClient != undefined)) {
                    accOfClient = regexCheck(accOfClient)
                }

                var delivererCusBic = answer.delivererCusBic;
                if ((delivererCusBic != null) && (delivererCusBic != '') && (delivererCusBic != undefined)) {
                    delivererCusBic = delivererCusBic.replace(slashRegex, "");
                    var tradeReceiverBic = delivererCusBic.split('/')[0];
                    var tradeDeliverCustodianBic = delivererCusBic.split('/')[1];

                }
                var placeofSett = answer.placeofSett;
                if ((placeofSett != null) && (placeofSett != '') && (placeofSett != undefined)) {
                    placeofSett = regexCheck(placeofSett)
                }
                var sellBuyBic = answer.sellBuyBic;
                if ((sellBuyBic != null) && (sellBuyBic != '') && (sellBuyBic != undefined)) {
                    sellBuyBic = sellBuyBic.replace(slashRegex, "");
                    var tradeBuyerBic = sellBuyBic.split('/')[0];
                    var tradeSellerBic = sellBuyBic.split('/')[1];

                }

                var settlementAccNumber = answer.counterSettAccNum;
                if ((settlementAccNumber != null) && (settlementAccNumber != '') && (settlementAccNumber != undefined)) {
                    settlementAccNumber = regexCheck(settlementAccNumber)
                }
                //handling special Characters
                var requestHeaders = [
                    answer.securityID,
                    answer.tradeDate,
                    answer.settlementDate,
                    answer.dealPrice,
                    answer.dealCurrency,
                    answer.settlementCurrency,
                    answer.settlementAmount,
                    answer.counterPartyRef,
                    cusRef,
                    answer.locCode,
                    answer.hmiIndicator,
                    answer.scripholIndicator,
                    answer.cashHoldIndicator,
                    answer.gdiIncidcator,
                    answer.payMethod,
                    answer.switchIndicator,
                    answer.switchAcc,
                    answer.counterParCode,
                    tradeReceiverBic,
                    tradeDeliverCustodianBic,
                    tradeBuyerBic,
                    tradeSellerBic,
                    placeofSett,
                    accOfClient,
                    answer.converAccSwitch,
                    settlementAccNumber,
                    susAccNum,
                    answer.amendChargesType,
                    answer.amendChargesCCY,
                    answer.amendChargesAmt,
                    answer.amendNSSC,
					answer.amendPurposeCode,
					answer.amendDataSource,
					answer.amendProprietyCode
                ];

                // request body header
                var taskFields = [
                    'bulk_id.security_id_sec_id',
                    'bulk_id.amend_trade_date',
                    'bulk_id.settlement_date',
                    'bulk_id.amend_deal_price',
                    'bulk_id.amend_deal_currency',
                    'bulk_id.amend_settlement_currency',
                    'bulk_id.amend_settlement_amount',
                    'bulk_id.counterparty_reference',
                    'bulk_id.customer_reference',
                    'bulk_id.amend_location_code',
                    'bulk_id.amend_hmi_indicator',
                    'bulk_id.amend_script_hold_indicator',
                    'bulk_id.amend_cash_hold_indicator',
                    'bulk_id.amend_gdi_indicator',
                    'bulk_id.amend_payment_method',
                    'bulk_id.amend_switch_indicator',
                    'bulk_id.amend_switch_account',
                    'bulk_id.amend_counterparty_code',
                    'bulk_id.amend_receiver_custodian_bic',
                    'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic',
                    'bulk_id.amend_buyer_bic',
                    'bulk_id.amend_seller_bic_buyer_bic',
                    'bulk_id.amend_place_of_settlement_bic',
                    'bulk_id.amend_a_c_of_client',
                    'bulk_id.amend_convert_to_account_switching',
                    'bulk_id.amend_counterparty_settlement_account_number',
                    'bulk_id.amend_suspense_account_number',
                    'bulk_id.amend_charges_type',
                    'bulk_id.amend_charges_ccy',
                    'bulk_id.amend_charges_amt',
                    'bulk_id.amend_nssc',
					'bulk_id.amend_si_purpose_code',
                    'bulk_id.amend_data_source_scheme',
					'bulk_id.amend_propriaty_code'
                ]; //populate amend values

                for (var i = 0; i < requestHeaders.length; i++) {
                    if ((requestHeaders[i] != '') && (requestHeaders[i] != null) && (requestHeaders[i] != undefined)) {
                        g_form.setValue(taskFields[i], requestHeaders[i]);
                    } else {
                        if (g_form.getValue('state') == 1 || g_form.getValue('state') == 2) {

                            g_form.clearValue(taskFields[i])
                        }
                    }
                }

                //MSSCUSTODY-6872

                var arrayFlag = 'true';
                var trdSettlementCurr = g_scratchpad.settlementCurrency;
                var trdSettlementDate = g_scratchpad.settlementDate;
                var tskAmendDate = g_form.getValue("bulk_id.amend_trade_date");
                var amendCurr = g_form.getValue("bulk_id.amend_settlement_currency");
                var amendSettAmt = g_form.getValue("bulk_id.amend_settlement_amount");
                var amendSettDate = g_form.getValue("bulk_id.settlement_date");
                var amendLocationCode = g_form.getValue("bulk_id.amend_location_code");
                var tradeId = g_form.getValue("trade_id");
                var gdiIndicator = g_form.getValue("bulk_id.amend_gdi_indicator");
                var placeOfSettlementBic = g_form.getValue("bulk_id.amend_place_of_settlement_bic");
                var amendScriptHoldIndicator = g_form.getValue("bulk_id.amend_script_hold_indicator");
                var amendSellerBuyerBic = g_form.getValue("bulk_id.amend_seller_bic_buyer_bic");
                var amendDealPrice = g_form.getValue("bulk_id.amend_deal_price");
                var amendDealCurrency = g_form.getValue("bulk_id.amend_deal_currency");
                var trdCashAccId = g_form.getValue("trade_id.cash_account_id");
                var amendBuyerSellerBic = g_form.getValue("bulk_id.amend_seller_bic_buyer_bic");
                var amendCustomerReference = g_form.getValue("bulk_id.customer_reference");
                var amendCashHoldIndicator = g_form.getValue("bulk_id.amend_cash_hold_indicator");
                var amendSuspenseAccNum = g_form.getValue("bulk_id.amend_suspense_account_number");
                var amendChargesType = g_form.getValue("bulk_id.amend_charges_type");
                var amendChargesCcy = g_form.getValue("bulk_id.amend_charges_ccy");
                var amendChargesAmt = g_form.getValue("bulk_id.amend_charges_amt");
                var amendDelivererReceivererBic = g_form.getValue("bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic");
                var amendCounterpartySettAccNum = g_form.getValue("bulk_id.amend_counterparty_settlement_account_number");
                var accOfClient = g_form.getValue("bulk_id.amend_a_c_of_client");
                var amendCounterpartyRef = g_form.getValue("bulk_id.counterparty_reference");
				var amendBuyerBic = g_form.getValue("bulk_id.amend_buyer_bic");      //7133
				var amendReceivererBic = g_form.getValue("bulk_id.amend_receiver_custodian_bic");      //7133

                var amendSecurityID = g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref').value;
                var tradeAmendSecurityID = g_form.getValue('bulk_id.security_id_sec_id');
                var amendSwitchAccount = g_form.getDisplayBox('bulk_id.amend_switch_account_ref').value;
                var tradeAmendSwitchAccount = g_form.getValue('bulk_id.amend_switch_account');
                var amendCounterpartyCode = g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref').value;
                var tradeAmendCounterpartyCode = g_form.getValue('bulk_id.amend_counterparty_code');
                var convertToAccSwitching = g_form.getValue("bulk_id.amend_convert_to_account_switching");

                // MSSCUSTODY-6226
                var legacyStatus = g_form.getValue('trade_id.legacy_status');
                var legacySubStatus = g_form.getValue('trade_id.legacy_sub_status');
                var switchIndicator = g_form.getValue('bulk_id.amend_switch_indicator');
                var transactionType = g_form.getValue('trade_id.transaction_type');
                var owningBusiness = g_scratchpad.owningBus;

                var trdDetails = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
                trdDetails.addParam('sysparm_name', 'evalAmendInputs');
                trdDetails.addParam('sysparm_trdSettlementDate', trdSettlementDate);
                trdDetails.addParam('sysparm_taskAmendDate', tskAmendDate);
                trdDetails.addParam('sysparm_trdSettlementCurr', trdSettlementCurr);
                trdDetails.addParam('sysparm_taskAmendCurr', amendCurr);
                trdDetails.addParam('sysparm_taskAmendSettAmt', amendSettAmt);
                trdDetails.addParam('sysparm_amendSettDate', amendSettDate);
                trdDetails.addParam('sysparm_taskAmendLocationCode', amendLocationCode);
                trdDetails.addParam('sysparm_tradeId', tradeId);
                trdDetails.addParam('sysparm_gdiIndicator', gdiIndicator);
                trdDetails.addParam('sysparm_placeOfSettlementBic', placeOfSettlementBic);
                trdDetails.addParam('sysparm_amendScriptHoldIndicator', amendScriptHoldIndicator);
                trdDetails.addParam('sysparm_amendSellerBuyerBic', amendSellerBuyerBic);
                trdDetails.addParam('sysparm_amendDealPrice', amendDealPrice);
                trdDetails.addParam('sysparm_amendDealCurrency', amendDealCurrency);
                trdDetails.addParam('sysparm_trdCashAccId', trdCashAccId);
                trdDetails.addParam('sysparm_amendBuyerSellerBic', amendBuyerSellerBic);
                trdDetails.addParam('sysparm_amendCustomerReference', amendCustomerReference);
                trdDetails.addParam('sysparm_amendCashHoldIndicator', amendCashHoldIndicator);
                trdDetails.addParam('sysparm_amendSuspenseAccNum', amendSuspenseAccNum); //to check
                trdDetails.addParam('sysparm_amendChargesType', amendChargesType);
                trdDetails.addParam('sysparm_amendChargesCcy', amendChargesCcy);
                trdDetails.addParam('sysparm_amendChargesAmt', amendChargesAmt);
                trdDetails.addParam('sysparm_amendDelivererReceivererBic', amendDelivererReceivererBic);
                trdDetails.addParam('sysparm_amendSwitchAccount', amendSwitchAccount);
                trdDetails.addParam('sysparm_amendSecurityID', amendSecurityID);
                trdDetails.addParam('sysparm_amendCounterpartyCode', amendCounterpartyCode);
                trdDetails.addParam('sysparm_accOfClient', accOfClient);
                trdDetails.addParam('sysparm_amendCounterpartySettAccNum', amendCounterpartySettAccNum);
                trdDetails.addParam('sysparm_amendCounterpartyRef', amendCounterpartyRef);
                trdDetails.addParam('sysparm_legacyStatus', legacyStatus);
                trdDetails.addParam('sysparm_legacySubStatus', legacySubStatus);
                trdDetails.addParam('sysparm_switchIndicator', switchIndicator);
                trdDetails.addParam('sysparm_owningBusiness', owningBusiness);
                trdDetails.addParam('sysparm_convertToAccSwitching', convertToAccSwitching);
                trdDetails.addParam('sysparm_transactionType', transactionType);
				trdDetails.addParam('sysparm_amendBuyerBic', amendBuyerBic);  //7133
				trdDetails.addParam('sysparm_amendReceivererBic', amendReceivererBic);  //7133

                trdDetails.addParam('sysparm_tradeAmendSecurityID', tradeAmendSecurityID);
                trdDetails.addParam('sysparm_tradeAmendSwitchAccount', tradeAmendSwitchAccount);
                trdDetails.addParam('sysparm_tradeAmendCounterpartyCode', tradeAmendCounterpartyCode);

                trdDetails.addParam('sysparm_arrayFlag', arrayFlag);
                trdDetails.getXMLAnswer(handleAmendResponse);
            }

        }
        //handling the prepopulation during onload when outcome is prepopulated
        //MSSCUSTODY-6872

        function handleAmendResponse(response) {

            if (response.length > -1) { //to limit if there are any warnings

                var fieldArray = {
                    'amendSecurityID': 'bulk_id.amend_security_id_sec_id_ref',
                    'tskAmendDate': 'bulk_id.amend_trade_date',
                    'amendSettDate': 'bulk_id.settlement_date',
                    'amendDealPrice': 'bulk_id.amend_deal_price',
                    'amendCurr': 'bulk_id.amend_settlement_currency',
                    'amendSettAmt': 'bulk_id.amend_settlement_amount',
                    'amendCounterpartyRef': 'bulk_id.counterparty_reference',
                    'amendCustomerReference': 'bulk_id.customer_reference',
                    'amendScriptHoldIndicator': 'bulk_id.amend_script_hold_indicator',
                    'amendCashHoldIndicator': 'bulk_id.amend_cash_hold_indicator',
                    'amendGdiIndicator': 'bulk_id.amend_gdi_indicator',
                    'amendSwitchAccount': 'bulk_id.amend_switch_account_ref',
                    'amendDelivererReceivererBic': 'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic',
                    'amendBuyerSellerBic': 'bulk_id.amend_seller_bic_buyer_bic',
                    'placeOfSettlementBic': 'bulk_id.amend_place_of_settlement_bic',
                    'amendSuspenseAccNum': 'bulk_id.amend_suspense_account_number',
                    'amendCounterpartySettAccNum': 'bulk_id.amend_counterparty_settlement_account_number',
                    'accOfClient': 'bulk_id.amend_a_c_of_client',
                    'amendChargesCcy': 'bulk_id.amend_charges_ccy',
                    'amendChargesAmt': 'bulk_id.amend_charges_amt',
                    'amendCounterpartyCode': 'bulk_id.amend_counterparty_code_ref',

                };
                response = response.split(',');

                for (var i = 0; i < response.length; i++) {
                    //g_form.addErrorMessage("in 139"+response[i]);

                    var responseField = response[i];
                    //g_form.addErrorMessage("amend 401 responseField= "+responseField);
                    if (fieldArray.hasOwnProperty(responseField)) {
                        var fieldValue = fieldArray[responseField];
                        var highlightField = g_form.getLabel(fieldValue);
                        highlightField.style.color = 'red';
                    }
                }
            } else {
                return;
            }
        }

        return;
    }

    /*Artifacts involved: 
	MSSCUSTODY-5197
	1) Client Script - MSS Task Prepopulate Amend from Trade - To pass Trade ID and Set values for Field
	2) Script Include - MSSCustodyAmendUtils Method - getTradeFieldvalues - To retrive Values from trade and send back to client
	3) Client Script - MSS Task Create Bulk for Amend - To pass values from bulk extended fields and send to below script inlcude to create bulk record
	4) Script Include - MSSAmendUtilsCore - Create bulk record and map to the task
	5) Property - x_hsb11_mss_c_proc.enableautomatedamend.market;
    6) Property - x_hsb11_mss_c_proc.enableautomatedamend.outcomes;
	This method is to prepropulate the amend fields for automated task when the outcome is selected as Amend related outcomes
    Once the form is submitted, this method executes and populates thefield values from the trade
	*/
    /*
    Eligibility Check Artifacts: 
    Script Include : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
    System Property: x_hsb11_mss_c_proc.enableautomatedamend.market - Only available markets will allow this script to execute
    System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes - Only available markets will allow this script to execute
    */


    //handling the prepopulation during onload when outcome is prepopulated
    var charRegex = /[^a-zA-Z0-9\s]/g;
    var taskType = g_scratchpad.tradeTaskType;
    var slashRegex = /\s/g;


    function regexCheck(inputValue) {
        var finalResult = inputValue.replace(charRegex, '');
        finalResult = finalResult.trim();
        finalResult = finalResult.replace(/\s/g, '');
        return finalResult;

    }

    if ((g_form.getValue('state') == 1 || g_form.getValue('state') == 2) && taskType == 'Maker') {
        var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtilsPassive');
        eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
        eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
        eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
        eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task_passive');
        eligbleCheck.getXMLAnswer(handleEligiblity);
    }



    function handleEligiblity(check) {
        //g_form.addInfoMessage('Eligibility' + check);
        if (check.toString() == 'true') {
            //pre populating the  values only if the outcome and market configured in the system property
            var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtilsPassive');
            ga.addParam('sysparm_name', 'getTradeFieldvalues');
            ga.addParam('sysparm_taskID', g_form.getUniqueValue());
            ga.addParam('sysparm_tradeID', g_form.getValue('trade_id'));
            ga.getXMLAnswer(populateField);
            //pre populating the  values only if the outcome and market configured in the system property
        }
    }

    function populateField(response) {
        if (response.toString() != 'false') { // populating only for active tasks
            var answer = JSON.parse(response);
            //handling special Characters
            var cusRef = answer.cusRef;
            if ((cusRef != null) && (cusRef != '') && (cusRef != undefined)) {
                cusRef = regexCheck(cusRef);
            }
            var susAccNum = answer.susAccNum; //commented for format matching in RPA
            if ((susAccNum != null) && (susAccNum != '') && (susAccNum != undefined)) {
                susAccNum = regexCheck(susAccNum)
            }
            var accOfClient = answer.accOfClient;
            if ((accOfClient != null) && (accOfClient != '') && (accOfClient != undefined)) {
                accOfClient = regexCheck(accOfClient)
            }

            var delivererCusBic = answer.delivererCusBic;
            if ((delivererCusBic != null) && (delivererCusBic != '') && (delivererCusBic != undefined)) {
                delivererCusBic = delivererCusBic.replace(slashRegex, "");
                var tradeReceiverBic = delivererCusBic.split('/')[0];
                var tradeDeliverCustodianBic = delivererCusBic.split('/')[1];

            }
            var placeofSett = answer.placeofSett;
            if ((placeofSett != null) && (placeofSett != '') && (placeofSett != undefined)) {
                placeofSett = regexCheck(placeofSett)
            }
            var sellBuyBic = answer.sellBuyBic;
            if ((sellBuyBic != null) && (sellBuyBic != '') && (sellBuyBic != undefined)) {
                sellBuyBic = sellBuyBic.replace(slashRegex, "");
                var tradeBuyerBic = sellBuyBic.split('/')[0];
                var tradeSellerBic = sellBuyBic.split('/')[1];

            }

            var settlementAccNumber = answer.counterSettAccNum;
            if ((settlementAccNumber != null) && (settlementAccNumber != '') && (settlementAccNumber != undefined)) {
                settlementAccNumber = regexCheck(settlementAccNumber)
            }
            //handling special Characters
            var requestHeaders = [
                answer.securityID,
                answer.tradeDate,
                answer.settlementDate,
                answer.dealPrice,
                answer.dealCurrency,
                answer.settlementCurrency,
                answer.settlementAmount,
                answer.counterPartyRef,
                cusRef,
                answer.locCode,
                answer.hmiIndicator,
                answer.scripholIndicator,
                answer.cashHoldIndicator,
                answer.gdiIncidcator,
                answer.payMethod,
                answer.switchIndicator,
                answer.switchAcc,
                answer.counterParCode,
                tradeReceiverBic,
                tradeDeliverCustodianBic,
                tradeBuyerBic,
                tradeSellerBic,
                placeofSett,
                accOfClient,
                answer.converAccSwitch,
                settlementAccNumber,
                susAccNum,
                answer.amendChargesType,
                answer.amendChargesCCY,
                answer.amendChargesAmt,
                answer.amendNSSC,
				answer.amendPurposeCode,
				answer.amendDataSource,
				answer.amendProprietyCode
            ];

            // request body header
            var taskFields = [
                'bulk_id.security_id_sec_id',
                'bulk_id.amend_trade_date',
                'bulk_id.settlement_date',
                'bulk_id.amend_deal_price',
                'bulk_id.amend_deal_currency',
                'bulk_id.amend_settlement_currency',
                'bulk_id.amend_settlement_amount',
                'bulk_id.counterparty_reference',
                'bulk_id.customer_reference',
                'bulk_id.amend_location_code',
                'bulk_id.amend_hmi_indicator',
                'bulk_id.amend_script_hold_indicator',
                'bulk_id.amend_cash_hold_indicator',
                'bulk_id.amend_gdi_indicator',
                'bulk_id.amend_payment_method',
                'bulk_id.amend_switch_indicator',
                'bulk_id.amend_switch_account',
                'bulk_id.amend_counterparty_code',
                'bulk_id.amend_receiver_custodian_bic',
                'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic',
                'bulk_id.amend_buyer_bic',
                'bulk_id.amend_seller_bic_buyer_bic',
                'bulk_id.amend_place_of_settlement_bic',
                'bulk_id.amend_a_c_of_client',
                'bulk_id.amend_convert_to_account_switching',
                'bulk_id.amend_counterparty_settlement_account_number',
                'bulk_id.amend_suspense_account_number',
                'bulk_id.amend_charges_type',
                'bulk_id.amend_charges_ccy',
                'bulk_id.amend_charges_amt',
                'bulk_id.amend_nssc',
				'bulk_id.amend_si_purpose_code',
                'bulk_id.amend_data_source_scheme',
				'bulk_id.amend_propriaty_code'
            ]; //populate amend values

            for (var i = 0; i < requestHeaders.length; i++) {
                if ((requestHeaders[i] != '') && (requestHeaders[i] != null) && (requestHeaders[i] != undefined)) {
                    g_form.setValue(taskFields[i], requestHeaders[i]);
                } else {
