    function handleAmendResponse(response) {

        if (response.length > -1) { //to limit if there are any warnings

            var fieldArray = {
                'amendSecurityID': 'bulk_id.amend_security_id_sec_id_ref',
                'tskAmendDate': 'bulk_id.amend_trade_date',
                'amendSettDate': 'bulk_id.settlement_date',
                'amendDealPrice': 'bulk_id.amend_deal_price',
                'amendCurr': 'bulk_id.amend_settlement_currency',
                'amendSettAmt': 'bulk_id.amend_settlement_amount',
                'amendCounterpartyRef': 'bulk_id.counterparty_reference',
                'amendCustomerReference': 'bulk_id.customer_reference',
                'amendScriptHoldIndicator': 'bulk_id.amend_script_hold_indicator',
                'amendCashHoldIndicator': 'bulk_id.amend_cash_hold_indicator',
                'amendGdiIndicator': 'bulk_id.amend_gdi_indicator',
                'amendSwitchAccount': 'bulk_id.amend_switch_account_ref',
                'amendDelivererReceivererBic': 'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic',
                'amendBuyerSellerBic': 'bulk_id.amend_seller_bic_buyer_bic',
                'placeOfSettlementBic': 'bulk_id.amend_place_of_settlement_bic',
                'amendSuspenseAccNum': 'bulk_id.amend_suspense_account_number',
                'amendCounterpartySettAccNum': 'bulk_id.amend_counterparty_settlement_account_number',
                'accOfClient': 'bulk_id.amend_a_c_of_client',
                'amendChargesCcy': 'bulk_id.amend_charges_ccy',
                'amendChargesAmt': 'bulk_id.amend_charges_amt',
                'amendCounterpartyCode': 'bulk_id.amend_counterparty_code_ref',

            };
            response = response.split(',');

            for (var i = 0; i < response.length; i++) {
                //g_form.addErrorMessage("in 139"+response[i]);

                var responseField = response[i];
                //g_form.addErrorMessage("amend 401 responseField= "+responseField);
                if (fieldArray.hasOwnProperty(responseField)) {
                    var fieldValue = fieldArray[responseField];
                    var highlightField = g_form.getLabel(fieldValue);
                    highlightField.style.color = 'red';
                }
            }
        } else {
            return;
        }
